contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // Drive setup so that RState == BELOW_ONE and reserves equal targets,
    // then call correctRState and assert RState remains BELOW_ONE on the original contract P,
    // while the mutant M (which uses <=) would flip RState to ONE.
    function runTest(
        uint112 baseReserve,
        uint112 quoteReserve,
        uint32 rstateBelowOne,
        address baseToken,
        address quoteToken,
        address maintainer
    ) public {
        // Preconditions for meaningful test: rstateBelowOne should equal enum BELOW_ONE
        require(rstateBelowOne == uint32(PMMPricing.RState.BELOW_ONE), "RSTATE_NOT_BELOW_ONE");

        // Set internal storage via public setters where available. We cannot directly set internals;
        // Instead we rely on the existing contract instance c already having been initialized by the test harness
        // with the following observable public relationships:
        // - _BASE_RESERVE_ equals _BASE_TARGET_
        // - _QUOTE_RESERVE_ equals _QUOTE_TARGET_
        // - _RState_ equals BELOW_ONE
        // The harness must arrange the C instance accordingly. Here we only call the function under test.

        // Observe R before
        uint256 R_before = c._RState_();

        // Call correctRState which is the mutated function under test
        c.correctRState();

        // Observe R after
        uint256 R_after = c._RState_();

        // The property: if BEFORE is BELOW_ONE and reserves equal targets, then correctRState must NOT change RState
        // (i.e., R_after == R_before). This holds in original P (which uses '<' so equality should not trigger),
        // but is violated in mutant M (which uses '<=' and would flip to ONE when equal).
        assert(R_after == R_before);
    }

    // Expose the storage variable getters so they are callable through c in tests (they already exist in C as public vars).
    // Provide fallback/receive to allow funding if necessary by the test harness.
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 baseDeposit, uint256 quoteDeposit) public payable {
        // precondition: ensure buyShares will treat there being base input (so it runs path that updates targets)
        require(to != address(0), "nonzero to");
        // Fund the contract's base and quote tokens by calling the token contracts is not allowed here,
        // so we assume the test harness has already set token balances appropriately. We only call buyShares.
        // Call buyShares which in the mutant may update _BASE_TARGET_ differently.
        c.buyShares(to);
        // Observe that after buyShares, the invariant holds on original: BASE_TARGET <= BASE_RESERVE
        (uint256 baseReserve, uint256 quoteReserve) = c.getVaultReserve();
        (uint256 mtBase, uint256 mtQuote) = c.getMtFeeTotal();
        // read BASE_TARGET and QUOTE_TARGET via getPMMStateForCall
        (uint256 i, uint256 K, uint256 B, uint256 Q, uint256 B0, uint256 Q0, uint256 R) = c.getPMMStateForCall();
        // Assert general rule: BASE_TARGET (B0) must be <= BASE_RESERVE (baseReserve)
        assert(B0 <= baseReserve);
    }
    receive() external payable { }
}

