contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 baseExtra, uint256 quoteExtra) public payable {
        // precondition: contract must be in BELOW_ONE and reserves equal targets
        (uint256 i, uint256 K, uint256 B, uint256 Q, uint256 B0, uint256 Q0, uint256 R) = c.getPMMStateForCall();
        require(R == uint256(0) + uint256(PMMPricing.RState.BELOW_ONE) || R == uint256(PMMPricing.RState.BELOW_ONE), "need BELOW_ONE state");
        require(B == B0, "require base reserve equals base target");
        // Transfer tokens into c by assuming caller already transferred tokens; here we only call buyShares which reads balances
        // Call buyShares: we cannot pass amounts directly to affect balances; the test assumes caller arranged token balances off-chain.
        // The observable we can get: shares minted to 'to' after call equals c.balanceOf(to)
        uint256 beforeBaseTarget = c._BASE_TARGET_();
        uint256 beforeBalanceTo = c.balanceOf(to);
        c.buyShares(to);
        uint256 afterBaseTarget = c._BASE_TARGET_();
        uint256 afterBalanceTo = c.balanceOf(to);
        // The increase in BASE_TARGET should not exceed the increase in shares credited to 'to'
        uint256 deltaTarget = afterBaseTarget >= beforeBaseTarget ? afterBaseTarget - beforeBaseTarget : 0;
        uint256 mintedShares = afterBalanceTo >= beforeBalanceTo ? afterBalanceTo - beforeBalanceTo : 0;
        assert(deltaTarget <= mintedShares);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 mintBase, uint256 mintQuote) public payable {
        // require sensible inputs: must produce a buyShares path with base input > 0
        require(to != address(0), true);
        // Precondition setup is not possible here (we can only call c). We assume caller has pre-funded c so that base/quote balances allow buyShares.
        // Call buyShares; the observable difference appears after this call in BASE_TARGET vs reserves
        c.buyShares(to);
        // Observe: BASE_TARGET must not exceed current BASE_RESERVE after buyShares
        (uint256 baseReserve, uint256 quoteReserve) = c.getVaultReserve();
        // access BASE_TARGET via getter: it's public so auto-getter exists
        uint256 baseTarget = c._BASE_TARGET_();
        assert(baseTarget <= baseReserve);
    }
    receive() external payable { }
}

